"""Make the example laps, the replay web page data and the animated replay that are published with the project.

Everything here is the project's own work, so it may be shared:
  * circuits generated by the project's own track generator (never Assetto Corsa tracks);
  * car files built from public data (``vehicles/library``);
  * drivers trained by the project.

Writes:
  ``docs/laps/...``            lap files (replayable in the web interface and on the published page)
  ``docs/laps/index.json``     the list of example laps (read by ``docs/index.html``)
  ``docs/replay.js``           copy of the viewer (``mv/ui/replay.js``) for the published page
  ``docs/img/lap_replay.gif``  the animation shown in the README

    python scripts/make_example_laps.py

Each example lists several generated circuits; the first one the driver laps
cleanly is used, and the console says which ones were tried - nothing is
hidden.
"""

from __future__ import annotations

import json
import math
import shutil
import sys
import tempfile
from pathlib import Path

import numpy as np

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from mv.envs.racing_env import EnvConfig  # noqa: E402
from mv.laps import EXAMPLE_DIR, laps_from_result, reference_lap_file, save_lap  # noqa: E402
from mv.planning.reference import reference_lap  # noqa: E402
from mv.rl.evaluate import evaluate  # noqa: E402
from mv.rl.ppo import load_policy  # noqa: E402
from mv.track.segments import segment_track  # noqa: E402
from mv.vehicle.params import find_vehicle, load_vehicle  # noqa: E402

EXAMPLES = [
    # (example name, car file, driver checkpoint, generator preset, track seeds to try in order)
    ("mv_gp_example", "porsche_taycan_turbo_gt_weissach", "runs/multi_v1/latest.pt", "gp", [11, 12, 13, 14, 15, 16, 17, 18]),
    ("mv_fs_example_1", "fs_generic_ev", "runs/fs_v1/best.pt", "fs_segments", [3]),
    ("mv_fs_example_2", "fs_generic_ev", "runs/fs_v1/best.pt", "fs_segments", [7]),
]


def env_cfg_of(ckpt: Path) -> EnvConfig:
    raw = json.loads((ckpt.parent / "config.json").read_text())["env"]
    return EnvConfig(**{k: tuple(v) if isinstance(v, list) else v for k, v in raw.items()})


def make(name: str, car: str, ckpt: str, preset: str, seeds: list[int]) -> tuple[dict, dict] | None:
    car_path = find_vehicle(car)
    vp = load_vehicle(car_path)
    ck = ROOT / ckpt
    if not ck.is_file():
        print(f"{name}: skipped, no driver {ckpt}")
        return None
    net, cfg = load_policy(ck, "cpu"), env_cfg_of(ck)
    for seed in seeds:
        track = segment_track(seed, preset, name=name)
        res = evaluate(net, vp, [track], "cpu", laps=3, cfg=cfg, record=True)[0]
        if not res.finished:
            print(f"{name}: circuit seed {seed} - not completed cleanly ({res.end_reason} at {res.distance_m:.0f} m), next")
            continue
        laps = laps_from_result(res, track, vp.name, f"{ck.parent.name} (trained driver)", "learned",
                                f"scripts/make_example_laps.py (circuit seed {seed})", ckpt,
                                car_file=str(car_path.relative_to(ROOT)).replace("\\", "/"))
        learned = min(laps, key=lambda l: l["meta"]["lap_time"])
        ref = reference_lap(track, vp)
        with tempfile.TemporaryDirectory() as tmp:
            p = Path(tmp) / "ref.npz"
            ref.save(p)
            reference = reference_lap_file(vp.name, track, p, vp.chassis.wheelbase_m,
                                           math.radians(vp.steering.max_wheel_angle_deg))
        for lap in (learned, reference):
            save_lap(lap, root=EXAMPLE_DIR)
        print(f"{name}: {vp.name} on circuit seed {seed}: learned {learned['meta']['lap_time']:.3f} s, "
              f"ideal {reference['meta']['lap_time']:.3f} s (+{(learned['meta']['lap_time'] / reference['meta']['lap_time'] - 1) * 100:.1f} %)")
        return learned, reference
    print(f"{name}: no clean lap on any of the circuits tried - example skipped")
    return None


def write_index() -> None:
    items = []
    for f in sorted(EXAMPLE_DIR.rglob("*.meta.json")):
        m = json.loads(f.read_text())
        m["path"] = f.relative_to(EXAMPLE_DIR).as_posix().replace(".meta.json", ".json")
        items.append(m)
    items.sort(key=lambda m: (m["kind"] == "reference", m["track"], m["lap_time"]))
    (EXAMPLE_DIR / "index.json").write_text(json.dumps(items, indent=1))
    shutil.copyfile(ROOT / "mv" / "ui" / "replay.js", ROOT / "docs" / "replay.js")
    print(f"wrote docs/laps/index.json ({len(items)} laps) and docs/replay.js")


def render_gif(lap: dict, ghost: dict, out: Path, seconds: float = 16.0, speedup: float = 3.0, fps: int = 12) -> None:
    """Animated replay: track map (line coloured by speed), chase camera, and a small dashboard."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    from matplotlib.animation import FuncAnimation, PillowWriter
    from matplotlib.collections import LineCollection
    from matplotlib.patches import Polygon, Rectangle

    BG, INK, MUTED, RED = "#14171c", "#e6e9ef", "#98a1b3", "#d5001c"
    s, g, tk, m = lap["samples"], ghost["samples"], lap["track"], lap["meta"]
    t, x, y, yaw, v = (np.asarray(s[k], float) for k in ("t", "x", "y", "yaw", "speed"))
    thr, brk, gear, steer = (np.asarray(s[k], float) for k in ("thr", "brk", "gear", "steer"))
    gt, gx, gy, gyaw = (np.asarray(g[k], float) for k in ("t", "x", "y", "yaw"))
    left, right = np.asarray(tk["left"]), np.asarray(tk["right"])
    ss, gs = np.maximum.accumulate(np.asarray(s["s"])), np.maximum.accumulate(np.asarray(g["s"]))

    fig = plt.figure(figsize=(8.0, 4.4), dpi=90, facecolor=BG)
    ax = fig.add_axes([0.0, 0.0, 0.56, 0.84]); ax.set_facecolor(BG); ax.set_aspect("equal"); ax.axis("off")
    cz = fig.add_axes([0.575, 0.36, 0.40, 0.62]); cz.set_facecolor("#1d2b1f"); cz.set_aspect("equal")
    cz.set_xticks([]); cz.set_yticks([]); [sp.set_visible(False) for sp in cz.spines.values()]
    hud = fig.add_axes([0.575, 0.0, 0.40, 0.34]); hud.axis("off"); hud.set_xlim(0, 1); hud.set_ylim(0, 1)
    for e in (left, right):
        ax.plot(*np.vstack([e, e[:1]]).T, color="#cfd5de", lw=0.8)
    pts = np.stack([x, y], 1)
    ax.add_collection(LineCollection(np.stack([pts[:-1], pts[1:]], 1), cmap="turbo", array=v[:-1] * 3.6, lw=2.2))
    ax.plot([left[0, 0], right[0, 0]], [left[0, 1], right[0, 1]], color="white", lw=2.5)
    ghost_dot, = ax.plot([], [], "o", ms=7, color="#a0aab9", mec="white")
    car_dot, = ax.plot([], [], "o", ms=9, color=RED, mec="white", mew=1.5)
    fig.text(0.015, 0.975, "Project MV", color=RED, fontsize=14, weight="bold", va="top")
    fig.text(0.015, 0.905, f"{m['car']} - generated circuit, never seen in training", color=MUTED, fontsize=8, va="top")
    # chase camera (heading up, 120 m across)
    W = 60.0
    cz.set_xlim(-W, W); cz.set_ylim(-0.75 * W, 1.25 * W)
    eL, = cz.plot([], [], color="#cfd5de", lw=1); eR, = cz.plot([], [], color="#cfd5de", lw=1)
    road = cz.fill([], [], color="#3b4049", zorder=0)[0]
    line, = cz.plot([], [], color="#ffd447", lw=1.5, alpha=0.8)
    ghost_car = Polygon(np.zeros((4, 2)), closed=True, color="#a0aab9", alpha=0.8); cz.add_patch(ghost_car)
    car_box = np.array([[-0.97, -2.3], [0.97, -2.3], [0.97, 2.3], [-0.97, 2.3]])
    cz.add_patch(Polygon(car_box, closed=True, color=RED, zorder=5))
    cz.text(0.03, 0.96, "chase camera", color=MUTED, fontsize=7, transform=cz.transAxes, va="top")
    # dashboard
    h_time = hud.text(0.0, 0.78, "", color=INK, fontsize=16, family="monospace")
    h_speed = hud.text(0.55, 0.78, "", color=INK, fontsize=16, family="monospace")
    h_gap = hud.text(0.0, 0.48, "", color=INK, fontsize=11, family="monospace")
    h_gear = hud.text(0.80, 0.48, "", color=MUTED, fontsize=11, family="monospace")
    hud.text(0.0, 0.18, "throttle", color=MUTED, fontsize=7); hud.text(0.0, 0.04, "brake", color=MUTED, fontsize=7)
    hud.add_patch(Rectangle((0.15, 0.17), 0.8, 0.09, color="#2a3039")); hud.add_patch(Rectangle((0.15, 0.03), 0.8, 0.09, color="#2a3039"))
    b_thr = Rectangle((0.15, 0.17), 0.0, 0.09, color="#3fbf6f"); b_brk = Rectangle((0.15, 0.03), 0.0, 0.09, color="#e05a55")
    hud.add_patch(b_thr); hud.add_patch(b_brk)
    hud.text(1.0, 0.98, f"driver {m['lap_time']:.3f} s   ideal {ghost['meta']['lap_time']:.3f} s   replay x{speedup:g}",
             color=MUTED, fontsize=7, ha="right", va="top")

    def to_cam(px, py, cx, cy, h):
        dx, dy = px - cx, py - cy
        c, sn = math.cos(-h + math.pi / 2), math.sin(-h + math.pi / 2)
        return dx * c - dy * sn, dx * sn + dy * c

    n_frames = int(min(seconds, t[-1] / speedup) * fps)

    def update(k):
        tt = k / fps * speedup
        i = min(np.searchsorted(t, tt), len(t) - 1)
        j = min(np.searchsorted(gt, tt), len(gt) - 1)
        car_dot.set_data([x[i]], [y[i]]); ghost_dot.set_data([gx[j]], [gy[j]])
        cx, cy, h = x[i], y[i], yaw[i]
        near = lambda e: e[np.hypot(e[:, 0] - cx, e[:, 1] - cy) < 1.6 * W]  # noqa: E731
        lx, ly = to_cam(*near(left).T, cx, cy, h); rx, ry = to_cam(*near(right).T, cx, cy, h)
        eL.set_data(lx, ly); eR.set_data(rx, ry)
        if len(lx) > 2 and len(rx) > 2:
            road.set_xy(np.vstack([np.stack([lx, ly], 1), np.stack([rx, ry], 1)[::-1]]))
        mk = np.hypot(x - cx, y - cy) < 1.6 * W
        ox, oy = to_cam(x[mk], y[mk], cx, cy, h); line.set_data(ox, oy)
        ghx, ghy = to_cam(gx[j], gy[j], cx, cy, h)
        rot = gyaw[j] - h
        R = np.array([[math.cos(rot), -math.sin(rot)], [math.sin(rot), math.cos(rot)]])
        ghost_car.set_xy(car_box @ R.T + np.array([ghx, ghy]))
        gap = tt - np.interp(ss[i], gs, gt)
        h_time.set_text(f"{int(tt // 60)}:{tt % 60:06.3f}")
        h_speed.set_text(f"{v[i] * 3.6:4.0f} km/h")
        h_gap.set_text(f"gap to ideal {gap:+.2f} s"); h_gap.set_color("#3fbf6f" if gap <= 0 else "#e05a55")
        h_gear.set_text(f"gear {int(gear[i])}" if gear[i] else "")
        b_thr.set_width(0.8 * thr[i]); b_brk.set_width(0.8 * brk[i])

    out.parent.mkdir(parents=True, exist_ok=True)
    FuncAnimation(fig, update, frames=n_frames, blit=False).save(out, writer=PillowWriter(fps=fps))
    plt.close(fig)
    print(f"wrote {out} ({out.stat().st_size / 1e6:.1f} MB, {n_frames} frames)")


def main() -> None:
    import torch
    torch.set_num_threads(4)
    if "--gif-only" in sys.argv:                 # re-render the animation from the published laps
        idx = json.loads((EXAMPLE_DIR / "index.json").read_text())
        first = next(m for m in idx if m["kind"] != "reference")
        ref = next(m for m in idx if m["kind"] == "reference" and m["track"] == first["track"] and m["car"] == first["car"])
        learned, reference = (json.loads((EXAMPLE_DIR / x["path"]).read_text()) for x in (first, ref))
        render_gif(learned, reference, ROOT / "docs" / "img" / "lap_replay.gif",
                   speedup=3.0 if learned["meta"]["lap_time"] > 40 else 1.5)
        return
    if EXAMPLE_DIR.is_dir():
        shutil.rmtree(EXAMPLE_DIR)
    made = [r for r in (make(*e) for e in EXAMPLES) if r]
    write_index()
    if made:
        learned, reference = made[0]
        render_gif(learned, reference, ROOT / "docs" / "img" / "lap_replay.gif",
                   speedup=3.0 if learned["meta"]["lap_time"] > 40 else 1.5)


if __name__ == "__main__":
    main()
